// Renders the app icon (white headset on a blue rounded square) into an
// .iconset directory. Regenerated by build.sh when this source changes; the resulting AppIcon.icns is
// cached in assets/.

import AppKit

guard CommandLine.arguments.count > 1 else {
    print("usage: makeicon <output.iconset>")
    exit(1)
}
let outDir = URL(fileURLWithPath: CommandLine.arguments[1])
try? FileManager.default.createDirectory(at: outDir, withIntermediateDirectories: true)

// (base point size, scale) pairs required by iconutil
let variants: [(Int, Int)] = [
    (16, 1), (16, 2), (32, 1), (32, 2), (128, 1), (128, 2),
    (256, 1), (256, 2), (512, 1), (512, 2),
]

for (base, scale) in variants {
    let pixels = CGFloat(base * scale)
    let image = NSImage(size: NSSize(width: pixels, height: pixels))
    image.lockFocus()

    // macOS-style rounded square with margin
    let margin = pixels * 0.09
    let rect = NSRect(x: margin, y: margin, width: pixels - margin * 2, height: pixels - margin * 2)
    let path = NSBezierPath(roundedRect: rect, xRadius: rect.width * 0.225, yRadius: rect.width * 0.225)
    NSGradient(
        starting: NSColor(calibratedRed: 0.20, green: 0.54, blue: 0.93, alpha: 1),
        ending: NSColor(calibratedRed: 0.08, green: 0.26, blue: 0.62, alpha: 1)
    )?.draw(in: path, angle: -90)

    let config = NSImage.SymbolConfiguration(pointSize: pixels * 0.5, weight: .semibold)
        .applying(NSImage.SymbolConfiguration(paletteColors: [.white]))
    if let symbol = NSImage(systemSymbolName: "headphones", accessibilityDescription: nil)?
        .withSymbolConfiguration(config) {
        let size = symbol.size
        let target = pixels * 0.56
        let ratio = target / max(size.width, size.height)
        let w = size.width * ratio, h = size.height * ratio
        symbol.draw(
            in: NSRect(x: (pixels - w) / 2, y: (pixels - h) / 2, width: w, height: h),
            from: .zero, operation: .sourceOver, fraction: 1
        )
    }
    image.unlockFocus()

    guard let tiff = image.tiffRepresentation,
          let rep = NSBitmapImageRep(data: tiff),
          let png = rep.representation(using: .png, properties: [:]) else { continue }
    let suffix = scale == 2 ? "@2x" : ""
    try? png.write(to: outDir.appendingPathComponent("icon_\(base)x\(base)\(suffix).png"))
}
print("iconset written to \(outDir.path)")
